"""HUMAN_REVIEW.md: every decision a human would have approved, with the evidence to decide."""

from __future__ import annotations

import json
from typing import Any

from factory.common.paths import REPO_ROOT
from factory.evidence import trace

APPS = ("claims-workbench", "approvals-kit")


def queue(app: str) -> list[dict[str, Any]]:
    m = trace.matrix(app)
    return [r for r in m["rules"] if r["needs_human_review"] or r["evidence"] == "failed"]


def write() -> None:
    lines = [
        "# Human review queue",
        "",
        "Generated by `factory evidence` from the committed artefacts. A rule is queued when a "
        "deterministic flag (fairness, contradiction, dead code, injection, low confidence, no "
        "executable oracle) or a failed parity check requires a person to decide. The model "
        "cannot remove a rule from this queue (ADR-008).",
        "",
    ]
    rbac = json.loads(
        (REPO_ROOT / "factory/fixtures/claims-workbench/rbac-decisions.json").read_text()
    )
    lines += ["## Migration decisions that change legacy privileges", ""]
    for d in rbac["decisions"]:
        lines.append(f"- **{d['id']}** ({d['status']}): {d['decision']} Finding: {d['finding']}")
    for app in APPS:
        q = queue(app)
        total = len(trace.matrix(app)["rules"])
        lines += ["", f"## {app}: {len(q)} of {total} rules", ""]
        lines += ["| Rule | Reasons | Evidence | Source | Statement |", "|---|---|---|---|---|"]
        for r in q:
            src = "<br>".join(x["source"] for x in r["links"])
            stmt = r["statement"].replace("|", "\\|").replace("\n", " ")
            lines.append(
                f"| {r['id']} | {'; '.join(r['review_reasons']) or 'failed parity'} "
                f"| {r['evidence']} | {src} | {stmt} |"
            )
    (REPO_ROOT / "HUMAN_REVIEW.md").write_text("\n".join(lines) + "\n")
